package com.brannenservices.fieldassistant

import android.app.Activity
import android.graphics.*
import android.os.Bundle
import android.view.*
import kotlin.math.*

class MainActivity : Activity() {
    private data class Flamingo(var x:Float,var hp:Int,val maxHp:Int,val boss:Boolean=false,var lastHit:Int=-1,var flash:Float=0f)
    private data class Pickup(val x:Float,var taken:Boolean=false)
    private data class Hazard(val x:Float,val w:Float)
    private enum class Action { JUMP, WHACK }

    override fun onCreate(b:Bundle?){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);window.setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_FULLSCREEN or View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY or View.SYSTEM_UI_FLAG_HIDE_NAVIGATION;setContentView(Game())}

    inner class Game:View(this@MainActivity){
        private val p=Paint(Paint.ANTI_ALIAS_FLAG); private val worldW=5600f
        private var px=220f;private var py=0f;private var vy=0f;private var ground=0f;private var cam=0f;private var face=1
        private var joyId:Int?=null;private var joyX=0f;private var joyY=0f;private val actions=mutableMapOf<Int,Action>()
        private var score=0;private var hp=100;private var beers=0;private var started=false;private var dead=false;private var won=false
        private var attack=0f;private var attackId=0;private var hurt=0f;private var time=0f;private var last=System.nanoTime();private var msg="";private var msgT=0f
        private var combo=0;private var comboT=0f;private var bestCombo=0;private var wave=1;private var bossIntro=false;private var rage=false
        private val birds=mutableListOf<Flamingo>();private val pickups=mutableListOf<Pickup>();private val hazards=mutableListOf<Hazard>()
        init{reset()}
        private fun reset(){px=220f;py=0f;vy=0f;cam=0f;face=1;score=0;hp=100;beers=0;dead=false;won=false;attack=0f;hurt=0f;time=0f;combo=0;comboT=0f;bestCombo=0;wave=1;bossIntro=false;rage=false;joyId=null;joyX=0f;joyY=0f;actions.clear();birds.clear();birds+=Flamingo(900f,2,2);birds+=Flamingo(1420f,2,2);birds+=Flamingo(2050f,3,3);birds+=Flamingo(2700f,3,3);birds+=Flamingo(3350f,4,4);birds+=Flamingo(4550f,10,10,true);pickups.clear();pickups+=Pickup(1180f);pickups+=Pickup(2420f);pickups+=Pickup(3600f);hazards.clear();hazards+=Hazard(1740f,110f);hazards+=Hazard(3020f,105f);hazards+=Hazard(3920f,115f)}
        override fun onDraw(c:Canvas){val n=System.nanoTime();val dt=((n-last)/1e9f).coerceAtMost(.04f);last=n;ground=height*.77f;if(py==0f)py=ground;if(started&&!dead&&!won)update(dt);world(c);hud(c);controls(c);overlay(c);postInvalidateOnAnimation()}
        private fun update(dt:Float){time+=dt;comboT=max(0f,comboT-dt);if(comboT<=0)combo=0;val m=if(abs(joyX)<.14f)0f else joyX;if(m!=0f){face=if(m>0)1 else -1;px=(px+m*430f*dt).coerceIn(55f,worldW-80f)};vy+=1550f*dt;py+=vy*dt;if(py>ground){py=ground;vy=0f};attack=max(0f,attack-dt);hurt=max(0f,hurt-dt);msgT=max(0f,msgT-dt);cam+=(px-width*.37f-cam)*min(1f,dt*7f);cam=cam.coerceIn(0f,max(0f,worldW-width));wave=when{px<1800->1;px<3700->2;else->3}
            for(b in birds){b.flash=max(0f,b.flash-dt);if(b.hp<=0)continue;val d=px-b.x;val range=if(b.boss)800f else 520f;if(abs(d)<range){val enr=b.boss&&b.hp<=b.maxHp/2;val sp=if(enr)180f else if(b.boss)115f else 88f;b.x+=(if(d>0)1 else -1)*sp*dt};if(attack>0&&b.lastHit!=attackId){val sd=(b.x-px)*face;if(sd in 15f..195f&&py>ground-165){b.hp--;b.lastHit=attackId;b.flash=.12f;b.x+=face*(if(b.boss)45 else 82);combo++;comboT=1.45f;bestCombo=max(bestCombo,combo);val mult=1+(combo-1)/3;score+=(if(b.boss)250 else 100)*mult;show(if(combo>=3)"$combo HIT COMBO — POOR DECISIONS MULTIPLIED" else "BONK.",.65f);if(b.boss&&b.hp<=b.maxHp/2&&!rage&&b.hp>0){rage=true;show("ALPHA FLAMINGO HAS ENTERED FULL KAREN MODE.",1.7f)};if(b.hp<=0){score+=if(b.boss)1800 else 300;if(b.boss)show("ALPHA FLAMINGO DOWN. HOA NOTIFIED.",2f)}}};if(abs(b.x-px)<(if(b.boss)95 else 62)&&py>ground-95&&hurt<=0){hp=max(0,hp-(if(b.boss)18 else 10));hurt=.75f;combo=0;comboT=0f;px+=(if(d>0)-105 else 105);show("THIS WAS A TERRIBLE PLAN.",.9f);if(hp<=0)dead=true}}
            for(h in hazards)if(abs(px-h.x)<h.w/2+28&&py>ground-72&&hurt<=0){hp=max(0,hp-8);hurt=.7f;combo=0;px+=if(px<h.x)-100 else 100;show("DEFEATED BY BACKYARD CLUTTER.",.8f);if(hp<=0)dead=true}
            for(q in pickups)if(!q.taken&&abs(q.x-px)<68&&py>ground-130){q.taken=true;beers++;hp=min(100,hp+25);score+=200;show("COLD ONE ACQUIRED. +25 QUESTIONABLE HEALTH.",1.2f)}
            val boss=birds.last();if(!bossIntro&&px>4050&&boss.hp>0){bossIntro=true;show("BOSS FIGHT: ALPHA FLAMINGO",2f)};if(boss.hp<=0&&px>5100)won=true}
        private fun show(s:String,t:Float){msg=s;msgT=t}
        private fun world(c:Canvas){val sky=LinearGradient(0f,0f,0f,ground,Color.rgb(45,176,225),Color.rgb(145,225,242),Shader.TileMode.CLAMP);p.shader=sky;c.drawRect(0f,0f,width.toFloat(),ground,p);p.shader=null;p.color=Color.rgb(255,235,130);c.drawCircle(width*.84f,height*.16f,height*.075f,p);p.color=Color.rgb(238,238,220);var fx=-((cam*.75f)%95f)-95;while(fx<width+95){c.drawRect(fx,ground-145,fx+72,ground-15,p);fx+=95};p.color=Color.rgb(232,208,157);c.drawRect(0f,ground,width.toFloat(),ground+height*.07f,p);p.color=Color.rgb(38,147,78);c.drawRect(0f,ground+height*.07f,width.toFloat(),height.toFloat(),p);sign(c,760f,"NO FLAMINGOS");sign(c,3200f,"HOA IS WATCHING");for(h in hazards)hazard(c,h);for(q in pickups)if(!q.taken)pickup(c,q);for(b in birds)if(b.hp>0)bird(c,b);player(c);sign(c,5250f,"BACKYARD EXIT")}
        private fun sign(c:Canvas,xw:Float,s:String){val x=xw-cam;if(x !in -180f..width+180f)return;p.color=Color.rgb(110,75,40);c.drawRect(x-5,ground-125,x+5,ground,p);p.color=Color.rgb(245,235,190);c.drawRect(x-100,ground-185,x+100,ground-120,p);p.color=Color.DKGRAY;p.typeface=Typeface.DEFAULT_BOLD;p.textAlign=Paint.Align.CENTER;p.textSize=17f;c.drawText(s,x,ground-145,p);p.textAlign=Paint.Align.LEFT}
        private fun hazard(c:Canvas,h:Hazard){val x=h.x-cam;if(x !in -130f..width+130f)return;p.color=Color.rgb(210,55,50);c.drawRoundRect(x-48,ground-58,x+48,ground+4,10f,10f,p);p.color=Color.WHITE;c.drawRect(x-52,ground-68,x+52,ground-53,p)}
        private fun pickup(c:Canvas,q:Pickup){val x=q.x-cam;if(x !in -100f..width+100f)return;val y=ground-60+sin(time*4+q.x*.01).toFloat()*7;p.color=Color.argb(90,255,240,120);c.drawCircle(x,y,42f,p);p.color=Color.LTGRAY;c.drawRoundRect(x-20,y-34,x+20,y+34,7f,7f,p);p.color=Color.rgb(55,135,205);c.drawRect(x-20,y-9,x+20,y+15,p);p.color=Color.WHITE;p.textAlign=Paint.Align.CENTER;p.textSize=12f;c.drawText("COLD",x,y+6,p);p.textAlign=Paint.Align.LEFT}
        private fun player(c:Canvas){if(hurt>0&&((hurt*12).toInt()%2==0))return;val x=px-cam;val y=py;p.color=Color.rgb(242,181,133);c.drawRect(x-23,y-3,x-8,y+42,p);c.drawRect(x+8,y-3,x+23,y+42,p);p.color=Color.rgb(42,71,148);c.drawRect(x-34,y-44,x+34,y+7,p);p.color=Color.WHITE;c.drawRect(x-31,y-110,x+31,y-44,p);p.color=Color.rgb(242,181,133);c.drawCircle(x,y-142,34f,p);p.color=Color.rgb(91,50,24);c.drawRect(x-37,y-174,x+25,y-158,p);c.drawRect(x-39,y-161,x-25,y-108,p);p.color=Color.BLACK;c.drawRect(x-25,y-150,x-4,y-141,p);c.drawRect(x+4,y-150,x+25,y-141,p);p.strokeWidth=20f;p.strokeCap=Paint.Cap.ROUND;p.color=Color.rgb(255,47,165);val sx=x+face*24;val sy=y-88;if(attack>0){val prog=(1-attack/.20f).coerceIn(0f,1f);val deg=if(face>0)-70+prog*105 else 250-prog*105;val r=Math.toRadians(deg.toDouble());c.drawLine(sx,sy,sx+cos(r).toFloat()*168,sy+sin(r).toFloat()*168,p)}else c.drawLine(sx,sy,x+face*72,y-128,p)}
        private fun bird(c:Canvas,b:Flamingo){val x=b.x-cam;if(x !in -190f..width+190f)return;val s=if(b.boss)1.55f else 1f;val y=ground-92*s;p.style=Paint.Style.STROKE;p.strokeWidth=13*s;p.strokeCap=Paint.Cap.ROUND;p.color=if(b.flash>0)Color.WHITE else if(b.boss&&b.hp<=b.maxHp/2)Color.rgb(205,28,68) else Color.rgb(255,88,145);c.drawOval(x-38*s,y-27*s,x+38*s,y+27*s,p);c.drawLine(x+18*s,y-18*s,x+28*s,y-92*s,p);c.drawCircle(x+46*s,y-111*s,22*s,p);c.drawLine(x+65*s,y-112*s,x+95*s,y-124*s,p);c.drawLine(x-14*s,y+20*s,x-20*s,ground+25,p);c.drawLine(x+12*s,y+20*s,x+20*s,ground+25,p);p.style=Paint.Style.FILL;p.color=Color.RED;c.drawCircle(x+50*s,y-116*s,5*s,p);if(b.boss){p.textAlign=Paint.Align.CENTER;p.typeface=Typeface.DEFAULT_BOLD;p.textSize=23f;p.color=Color.YELLOW;c.drawText("ALPHA FLAMINGO",x,y-170,p);p.color=Color.argb(180,0,0,0);c.drawRect(x-85,y-158,x+85,y-145,p);p.color=Color.RED;c.drawRect(x-85,y-158,x-85+170*b.hp.toFloat()/b.maxHp,y-145,p);p.textAlign=Paint.Align.LEFT}}
        private fun hud(c:Canvas){val pad=height*.035f;p.color=Color.argb(155,0,0,0);c.drawRoundRect(pad,pad,width*.35f,pad+height*.095f,18f,18f,p);p.color=Color.WHITE;p.typeface=Typeface.MONOSPACE;p.textSize=height*.035f;c.drawText("HOLD MY BEER",pad*1.7f,pad+height*.04f,p);p.color=Color.DKGRAY;c.drawRect(pad*1.7f,pad+height*.058f,width*.32f,pad+height*.08f,p);p.color=if(hp>35)Color.rgb(245,194,48) else Color.RED;c.drawRect(pad*1.7f,pad+height*.058f,pad*1.7f+(width*.32f-pad*1.7f)*hp/100f,pad+height*.08f,p);p.textAlign=Paint.Align.CENTER;p.typeface=Typeface.DEFAULT_BOLD;p.textSize=height*.05f;p.color=Color.YELLOW;c.drawText("FLORIDA MAN",width/2f,pad+height*.045f,p);p.textSize=height*.025f;p.color=Color.WHITE;c.drawText("POOL NOODLE PANIC • WAVE $wave/3",width/2f,pad+height*.076f,p);p.textAlign=Paint.Align.RIGHT;p.textSize=height*.032f;c.drawText("SCORE $score",width-pad*1.7f,pad+height*.036f,p);p.textSize=height*.025f;c.drawText("COLD ONES $beers/3",width-pad*1.7f,pad+height*.069f,p);if(combo>=2){p.textAlign=Paint.Align.CENTER;p.textSize=height*.045f;p.color=Color.rgb(255,130,45);c.drawText("$combo HIT COMBO!",width/2f,height*.18f,p)};if(msgT>0&&started&&!dead&&!won){p.textAlign=Paint.Align.CENTER;p.textSize=min(27f,height*.034f);p.color=Color.WHITE;c.drawText(msg,width/2f,height*.235f,p)};p.textAlign=Paint.Align.LEFT}
        private fun controls(c:Canvas){val jr=min(height*.115f,96f);val jx=max(96f,height*.16f);val jy=height-max(82f,height*.14f);p.color=Color.argb(105,0,0,0);c.drawCircle(jx,jy,jr,p);p.color=Color.argb(210,35,35,35);c.drawCircle(jx+joyX*jr*.58f,jy+joyY*jr*.58f,jr*.46f,p);val r=min(height*.085f,78f);val y=height-r-height*.035f;button(c,width-r-height*.035f-r*2.25f,y,r,"JUMP");button(c,width-r-height*.035f,y,r,"WHACK")}
        private fun button(c:Canvas,x:Float,y:Float,r:Float,s:String){p.color=Color.argb(125,0,0,0);c.drawCircle(x,y,r,p);p.color=Color.WHITE;p.typeface=Typeface.DEFAULT_BOLD;p.textAlign=Paint.Align.CENTER;p.textSize=r*.32f;c.drawText(s,x,y+p.textSize*.34f,p);p.textAlign=Paint.Align.LEFT}
        private fun overlay(c:Canvas){if(started&&!dead&&!won)return;p.color=Color.argb(195,0,0,0);c.drawRect(0f,height*.24f,width.toFloat(),height*.70f,p);p.textAlign=Paint.Align.CENTER;p.typeface=Typeface.DEFAULT_BOLD;p.color=Color.WHITE;if(!started){p.textSize=height*.064f;c.drawText("TAP TO START THE BAD DECISIONS",width/2f,height*.41f,p);p.textSize=height*.032f;p.color=Color.YELLOW;c.drawText("SURVIVE 3 WAVES. DEFEAT THE ALPHA FLAMINGO.",width/2f,height*.50f,p);p.color=Color.WHITE;c.drawText("MOVE • JUMP • WHACK • COLLECT COLD ONES",width/2f,height*.58f,p)}else if(dead){p.textSize=height*.075f;p.color=Color.rgb(255,90,70);c.drawText("WELL, THAT ESCALATED.",width/2f,height*.44f,p);p.textSize=height*.038f;p.color=Color.WHITE;c.drawText("BEST COMBO $bestCombo • TAP TO TRY AGAIN",width/2f,height*.55f,p)}else{p.textSize=height*.07f;p.color=Color.YELLOW;c.drawText("BACKYARD SURVIVED. SOMEHOW.",width/2f,height*.43f,p);p.textSize=height*.036f;p.color=Color.WHITE;c.drawText("SCORE $score • BEST COMBO $bestCombo • COLD ONES $beers/3",width/2f,height*.54f,p);c.drawText("TAP TO RUN IT AGAIN",width/2f,height*.62f,p)};p.textAlign=Paint.Align.LEFT}
        private fun jump(){if(py>=ground-4)vy=-720f};private fun whack(){if(attack<=0){attackId++;attack=.20f}}
        override fun onTouchEvent(e:MotionEvent):Boolean{when(e.actionMasked){MotionEvent.ACTION_DOWN,MotionEvent.ACTION_POINTER_DOWN->{val i=e.actionIndex;val id=e.getPointerId(i);val x=e.getX(i);val y=e.getY(i);if(!started){started=true;last=System.nanoTime();return true};if(dead||won){reset();started=true;last=System.nanoTime();return true};val jx=max(96f,height*.16f);val jy=height-max(82f,height*.14f);val jr=min(height*.115f,96f);if(joyId==null&&hypot(x-jx,y-jy)<=jr*1.45f){joyId=id;setJoy(x,y)}else{val r=min(height*.085f,78f);val by=height-r-height*.035f;val wx=width-r-height*.035f;val jmp=wx-r*2.25f;val a=when{hypot(x-wx,y-by)<=r*1.22f->Action.WHACK;hypot(x-jmp,y-by)<=r*1.22f->Action.JUMP;else->null};if(a!=null){actions[id]=a;if(a==Action.JUMP)jump() else whack()}}};MotionEvent.ACTION_MOVE->{joyId?.let{id->val i=e.findPointerIndex(id);if(i>=0)setJoy(e.getX(i),e.getY(i))}};MotionEvent.ACTION_UP,MotionEvent.ACTION_POINTER_UP->{val id=e.getPointerId(e.actionIndex);if(id==joyId){joyId=null;joyX=0f;joyY=0f};actions.remove(id)};MotionEvent.ACTION_CANCEL->{joyId=null;joyX=0f;joyY=0f;actions.clear()}};return true}
        private fun setJoy(x:Float,y:Float){val cx=max(96f,height*.16f);val cy=height-max(82f,height*.14f);val r=min(height*.115f,96f);val dx=x-cx;val dy=y-cy;val d=hypot(dx,dy);if(d<=r||d==0f){joyX=(dx/r).coerceIn(-1f,1f);joyY=(dy/r).coerceIn(-1f,1f)}else{joyX=dx/d;joyY=dy/d}}
    }
}
